package pzvrphysicality;

import java.lang.reflect.*;import java.util.*;import org.joml.Matrix4f;
import local.pzvr.Engine;import viewpoint.render.*;import zombie.iso.objects.IsoWindow;import static org.lwjgl.opengl.GL33.*;

/** Original native output scope and two-eye admission for one immutable progressed window packet. */
public final class WindowMotionRenderHook {
 private record Scope(SceneData scene,FrameContext frame,Targets output,long xrFrame,int eye,int fbo,int depth,int width,int height,int[] viewport,float[] projection,long generation,long input){Scope{viewport=viewport.clone();projection=projection.clone();}}
 private record Prepared(WindowMotion.Entry entry,WindowMotion.Packet packet,List<WindowMotionRenderer.Draw> opaque,List<WindowMotionRenderer.Draw> glass){}
 private record Work(Scope scope,List<Prepared> rows){}
 private static final class Receipt {final WindowMotion.Entry entry;final WindowMotion.Packet packet;final Scope[] eyes=new Scope[2];Receipt(WindowMotion.Entry entry,WindowMotion.Packet packet){this.entry=entry;this.packet=packet;}boolean complete(){return eyes[0]!=null&&eyes[1]!=null&&eyes[0].xrFrame==packet.frame()&&eyes[1].xrFrame==packet.frame()&&eyes[0].generation==packet.generation()&&eyes[1].generation==packet.generation()&&eyes[0].input==packet.input()&&eyes[1].input==packet.input();}}
 private static final Map<IsoWindow,Receipt> receipts=new WeakHashMap<>();private static final ThreadLocal<Work> work=new ThreadLocal<>();private static Field frameField,targetsField,irisField,fboField,viewportField,textureId;private static WindowMotionRenderer renderer;private static volatile String detail="Window outputs waiting";
 private static Field field(Class<?> type,String name)throws ReflectiveOperationException{var f=type.getDeclaredField(name);f.setAccessible(true);return f;}
 public static String status(){synchronized(receipts){return detail+"; original paired receipts "+receipts.size();}}
 private static Scope scope(SceneData scene,WorldRigFrame rig)throws ReflectiveOperationException{
  if(frameField==null){frameField=field(WorldRenderer.class,"frame");targetsField=field(WorldRenderer.class,"targets");irisField=field(WorldRenderer.class,"irisDrawn");fboField=field(FrameContext.class,"outputDrawFbo");viewportField=field(FrameContext.class,"viewport");textureId=field(zombie.core.textures.TextureID.class,"id");}
  var frame=(FrameContext)frameField.get(null);var output=(Targets)targetsField.get(null);int eye=Engine.currentEye();long xrFrame=Engine.frameNumber();var actor=zombie.characters.IsoPlayer.players.length==0?null:zombie.characters.IsoPlayer.players[0];if(frame==null||output==null||frame.scene!=scene||scene==null||scene.cameraCut||rig==null||!rig.fresh(System.nanoTime())||rig.actor()!=actor||eye<0||eye>1||xrFrame<0||irisField.getBoolean(null)||frame.panini!=null&&frame.panini.on()||!frame.viewProjection.isFinite()||Math.abs(frame.viewProjection.determinant())<1e-12)throw new IllegalStateException("Window current native eye prerequisites");
  int[] actual=new int[4];glGetIntegerv(GL_VIEWPORT,actual);int fbo=fboField.getInt(frame);if(glGetInteger(GL_DRAW_FRAMEBUFFER_BINDING)!=fbo||!Arrays.equals(actual,(int[])viewportField.get(frame))||actual[2]!=frame.outputWidth||actual[3]!=frame.outputHeight||!glIsTexture(output.depth)||frame.outputWidth<1||frame.outputHeight<1)throw new IllegalStateException("Window native output changed");return new Scope(scene,frame,output,xrFrame,eye,fbo,output.depth,frame.outputWidth,frame.outputHeight,actual,frame.viewProjection.get(new float[16]),rig.generation(),rig.inputTime());
 }
 private static boolean same(Scope scope)throws ReflectiveOperationException{if(!WindowMotion.eligible()||Engine.latestInput==null||Engine.latestInput.time()!=scope.input||WorldRigCapture.latest==null||WorldRigCapture.latest.generation()!=scope.generation||frameField.get(null)!=scope.frame||targetsField.get(null)!=scope.output||scope.frame.scene!=scope.scene||Engine.frameNumber()!=scope.xrFrame||Engine.currentEye()!=scope.eye||scope.output.depth!=scope.depth||fboField.getInt(scope.frame)!=scope.fbo||scope.frame.outputWidth!=scope.width||scope.frame.outputHeight!=scope.height||!Arrays.equals(scope.projection,scope.frame.viewProjection.get(new float[16])))return false;int[] actual=new int[4];glGetIntegerv(GL_VIEWPORT,actual);return glGetInteger(GL_DRAW_FRAMEBUFFER_BINDING)==scope.fbo&&Arrays.equals(actual,scope.viewport)&&glIsTexture(scope.depth);}
 public static boolean warmed(IsoWindow window,WindowMotionCapture.Pair pair){synchronized(receipts){var r=receipts.get(window);long now=System.nanoTime();return r!=null&&r.complete()&&WindowMotion.focused()&&r.entry.epoch==WindowMotion.epoch()&&now>=r.packet.time()&&now-r.packet.time()<WindowMotion.FRESH&&r.entry.pair.closed().identity()==pair.closed().identity()&&r.entry.pair.open().identity()==pair.open().identity()&&WorldRigCapture.latest!=null&&WorldRigCapture.latest.generation()==r.packet.generation()&&WindowMotion.current(r.entry);}}
 public static WindowMotion.Packet publication(IsoWindow window){synchronized(receipts){var r=receipts.get(window);if(r==null||!r.complete()||!r.entry.suppressed()||!WindowMotion.current(r.entry)||window.IsOpen()!=r.packet.open())return null;long now=System.nanoTime();var rig=WorldRigCapture.latest;var input=Engine.latestInput;if(!WindowMotion.focused()||input==null||!input.focused()||rig==null||!rig.fresh(now)||rig.generation()!=r.packet.generation()||now<r.packet.time()||now-r.packet.time()>=WindowMotion.FRESH||!WindowMotion.visible(r.entry,r.eyes[0].scene)||!WindowMotion.visible(r.entry,r.eyes[1].scene))return null;return r.packet;}}
 private static WindowMotionRenderer.Draw draw(float[] mesh,WindowMotion.Entry entry,WindowMotion.Packet packet,WorldRigFrame rig,int closed,int open,boolean moving){var square=entry.square();var camera=rig.camera();var mount=new Matrix4f().translation((float)(camera.x()-square.getX()-.5),(float)(square.getZ()*Math.sqrt(6)+entry.rise-camera.height()),(float)(camera.y()-square.getY()-.5)).scale(-1,1,-1);var pair=entry.pair();return new WindowMotionRenderer.Draw(pair.closed().projection().render(mesh,pair.profile().north(),0),mount,closed,open,pair.closedArt().mapping(),pair.openArt().mapping(),(float)packet.geometry().progress(),pair.profile().middle(),pair.profile().travel(),moving);}
 private static void omitted(WindowMotion.Entry entry){synchronized(receipts){var source=entry.source();var receipt=receipts.get(source);if(receipt!=null&&receipt.entry==entry)receipts.remove(source);}WindowMotion.restore(entry);}
 public static void drawOpaque(SceneData scene){
  if(!WindowMotion.enabled())return;if(!WindowMotion.eligible()){rejectScope();return;}long now=System.nanoTime();var rig=WorldRigCapture.forScene(scene,now);
  try{var scope=scope(scene,rig);if(renderer==null)renderer=new WindowMotionRenderer();renderer.prepare(scope.width,scope.height);var rows=new ArrayList<Prepared>();
   for(var entry:WindowMotion.tracked()){if(rows.size()>=8||!WindowMotion.visible(entry,scene)){omitted(entry);continue;}var pair=entry.pair();int a=textureId.getInt(pair.closedArt().page()),b=textureId.getInt(pair.openArt().page());if(a<=0||b<=0||a==scope.depth||b==scope.depth||!glIsTexture(a)||!glIsTexture(b)){omitted(entry);continue;}var packet=WindowMotion.packet(entry,rig,scope.xrFrame,now);if(packet==null){omitted(entry);continue;}var opaque=new ArrayList<WindowMotionRenderer.Draw>();var glass=new ArrayList<WindowMotionRenderer.Draw>();var fixed=WindowMotionGeometry.inner(pair.profile(),packet.geometry().fixed());var lower=packet.geometry().lower();var pane=packet.geometry().glass();if(fixed.length>0)opaque.add(draw(fixed,entry,packet,rig,a,b,false));if(lower.length>0)opaque.add(draw(lower,entry,packet,rig,a,b,true));if(pane.length>0){opaque.add(draw(pane,entry,packet,rig,a,b,false));glass.add(draw(pane,entry,packet,rig,a,b,false));}if(opaque.isEmpty()){omitted(entry);continue;}rows.add(new Prepared(entry,packet,List.copyOf(opaque),List.copyOf(glass)));
   }
   var workValue=new Work(scope,List.copyOf(rows));work.set(workValue);for(boolean composite:new boolean[]{false,true}){var draws=new ArrayList<WindowMotionRenderer.Draw>();for(var row:rows)if(row.entry.suppressed()==composite)draws.addAll(row.opaque);if(!draws.isEmpty())renderer.draw(draws,scope.frame.viewProjection,scope.depth,scope.width,scope.height,false,composite);}if(!same(scope))throw new IllegalStateException("Window opaque output retired");detail="Window original opaque pieces drawn "+rows.size();
  }catch(ReflectiveOperationException|RuntimeException|LinkageError unavailable){rejectScope();detail="Window native fallback requested: "+unavailable.getClass().getSimpleName();}
 }
 public static void drawGlass(SceneData scene){var w=work.get();work.remove();if(w==null)return;
  try{if(w.scope.scene!=scene||!same(w.scope))throw new IllegalStateException("Window transparent output replaced");var rows=new ArrayList<Prepared>();for(var row:w.rows){if(!WindowMotion.current(row.entry)||!WindowMotion.visible(row.entry,scene)||row.entry.source().IsOpen()!=row.packet.open()){omitted(row.entry);continue;}rows.add(row);}for(boolean composite:new boolean[]{false,true}){var draws=new ArrayList<WindowMotionRenderer.Draw>();for(var row:rows)if(row.entry.suppressed()==composite)draws.addAll(row.glass);if(!draws.isEmpty())renderer.draw(draws,w.scope.frame.viewProjection,w.scope.depth,w.scope.width,w.scope.height,true,composite);}if(!same(w.scope))throw new IllegalStateException("Window transparent output retired");
   synchronized(receipts){var admitted=Collections.newSetFromMap(new IdentityHashMap<IsoWindow,Boolean>());for(var row:rows){var source=row.entry.source();admitted.add(source);var previous=receipts.get(source);if(previous==null||previous.entry!=row.entry||previous.packet!=row.packet)previous=new Receipt(row.entry,row.packet);previous.eyes[w.scope.eye]=w.scope;receipts.put(source,previous);if(previous.complete()&&!row.entry.suppressed())WindowMotion.redraw(row.entry);}var stale=receipts.values().iterator();while(stale.hasNext()){var receipt=stale.next();if(!admitted.contains(receipt.entry.source())){WindowMotion.restore(receipt.entry);stale.remove();}}}detail="Window original material outputs completed, eye "+w.scope.eye;
  }catch(ReflectiveOperationException|RuntimeException|LinkageError unavailable){rejectScope();detail="Window transparent fallback requested: "+unavailable.getClass().getSimpleName();}
 }
 public static void rejectScope(){work.remove();synchronized(receipts){receipts.clear();}WindowMotion.reject();}
 private WindowMotionRenderHook(){}
}
